// ---- Shared helpers for the Province > City > District > Suburb picker ----
function areaProvinces(){ return Object.keys(AREAS); }
function areaCities(province){ return province && AREAS[province] ? Object.keys(AREAS[province]) : []; }
function areaDistricts(province,city){ return province && city && AREAS[province] && AREAS[province][city] ? Object.keys(AREAS[province][city]) : []; }
function areaSuburbs(province,city,district){ return province && city && district && AREAS[province]?.[city]?.[district] ? AREAS[province][city][district] : []; }
